import{_ as t,o,c as a,ag as i}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"RichTextEditor (CC) — figma notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/cc/components/RichTextEditor/RichTextEditor.figma-notes.md","filePath":"public/demos/src/cc/components/RichTextEditor/RichTextEditor.figma-notes.md"}'),r={name:"public/demos/src/cc/components/RichTextEditor/RichTextEditor.figma-notes.md"};function d(n,e,s,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="richtexteditor-cc-—-figma-notes" tabindex="-1">RichTextEditor (CC) — figma notes <a class="header-anchor" href="#richtexteditor-cc-—-figma-notes" aria-label="Permalink to &quot;RichTextEditor (CC) — figma notes&quot;">​</a></h1><p><strong>Tier:</strong> Component · <strong>Status:</strong> CODE-FIRST (designer, 2026-09-29). <strong>Drawn in Figma 2026-09-30</strong> (<code>3939:23167</code>). The only match is <code>TextEditor</code> in the old &quot;Control Centre Presentation&quot; library (2023). Flagged for Figma; check with Mark before any push.</p><p>The record screens&#39; rich-text fields (Introduction, Main Body, Text 2–5) run <strong>TinyMCE 8.8.2</strong>, the same editor and version the live Control Centre uses (affino.com, read 2026-09-29: six editors per article). The config mirrors live:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Value (as live)</th></tr></thead><tbody><tr><td>toolbar</td><td>restoredraft · undo redo · styles · bold italic underline · align ×4 · link <strong>+ Insert image</strong> · bullist numlist outdent indent · pastetext removeformat · ltr rtl · table · fullscreen</td></tr><tr><td>plugins</td><td>autosave lists advlist link table fullscreen wordcount directionality nonbreaking</td></tr><tr><td>style formats</td><td>Headings 1–6 · Inline (bold … code) · Blocks (Paragraph, Quote = <code>div.aos-ShortQuote</code>)</td></tr><tr><td>height / statusbar / menubar</td><td>300 · on (path + word count) · off</td></tr></tbody></table><p><strong>Added beyond live:</strong> <code>Insert image</code> opens the Selector Type=Media (<code>window.selector.openMedia</code>) and inserts the picked image at the cursor. Live&#39;s image plugin uses TinyMCE&#39;s URL dialog.</p><h2 id="theming" tabindex="-1">Theming <a class="header-anchor" href="#theming" aria-label="Permalink to &quot;Theming&quot;">​</a></h2><ul><li><strong>Chrome</strong> (RichTextEditor.css), scoped under <code>.rich-text</code> to out-rank the oxide skin: the frame is the Textarea&#39;s <code>--ai-border-secondary</code> / <code>--ai-radius-md</code>, with a brand border on focus. The toolbar is <code>--ai-surface-primary</code>, toolbar controls (buttons, the Styles dropdown) have the input radius <code>--ai-radius-md</code>, and the Styles dropdown is styled as our Select / Input field (surface-primary, border-secondary, brand border on hover and open, the Input focus ring) at TinyMCE&#39;s toolbar height, a hovered button <code>--ai-surface-minimal</code>, an active one <code>--ai-surface-brand-soft</code> / <code>--ai-text-brand</code>. The statusbar uses <code>--ai-text-secondary</code> at <code>--ai-font-fixed-xxs</code>. Menus and dialogs keep oxide.</li><li><strong>Content</strong> (RichTextEditor.content.css, inside the iframe): the token files are loaded into the iframe and the page&#39;s <code>data-brand</code> / <code>data-theme</code> are mirrored onto its <code>&lt;html&gt;</code>, so body, headings, links, lists, quote and table resolve the page&#39;s tokens. It follows a theme switch live.</li><li><strong>Dark:</strong> the <code>oxide-dark</code> skin is picked at init, so the chrome follows a theme switch on the next load.</li></ul><h2 id="fallback" tabindex="-1">Fallback <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;Fallback&quot;">​</a></h2><p>The textarea is the form value (synced on every change). If the CDN is unavailable, it stays a plain textarea.</p><h2 id="handover" tabindex="-1">Handover <a class="header-anchor" href="#handover" aria-label="Permalink to &quot;Handover&quot;">​</a></h2><p><code>record-rich-text</code>: swap the jsDelivr build and <code>license_key: &#39;gpl&#39;</code> for the product&#39;s own TinyMCE build, licence and config (content_css = the site&#39;s LiveEditForm.css + CustomFonts.css).</p><h2 id="figma-build-2026-09-30" tabindex="-1">Figma build 2026-09-30 <a class="header-anchor" href="#figma-build-2026-09-30" aria-label="Permalink to &quot;Figma build 2026-09-30&quot;">​</a></h2><p><strong>RichTextEditor <code>3939:23167</code></strong> (State Default | Focus = brand border) and <strong>RichTextEditor / ToolbarButton <code>3939:22798</code></strong> (32px, Icon swap). Toolbar groups in the live order; Lucide equivalents stand in for TinyMCE&#39;s oxide icons (stroke icons, so they read a touch lighter than the file&#39;s filled ones). FieldRow gained <strong>Type=Rich Text</strong> (Wide <code>3941:149242</code>, Stacked <code>3941:149395</code>).</p>',13)])])}const m=t(r,[["render",d]]);export{g as __pageData,m as default};
